input.command:
cat > spec/book_time.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n' > "$t"
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 9am 10:00 x >/dev/null 2>&1; [ $? = 2 ] || { echo "bad start should exit 2"; fail=1; }
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 09:00 10am x >/dev/null 2>&1; [ $? = 2 ] || { echo "bad end should exit 2"; fail=1; }
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 09:00 10am x 2>&1 >/dev/null | grep -q '^bad time: 10am (expected HH:MM)$' || { echo "bad end should say which time"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 0 ] || { echo "a rejected booking was stored"; fail=1; }
rm -f "$t"; exit $fail
EOF
bash spec/book_time.spec.sh; echo "spec exit=$?"
